<script setup>
import { ref, watch } from 'vue'
import {licenses,aiDeclaration} from '../shared/declarations.mjs'
import { useRoute } from 'vue-router'
const route=useRoute(), result=ref({}), error=ref(''), busy=ref(false), me=ref(null), studio=ref({asset:[],work:[],collection:[],profile:[]}), active=ref(0)
const form=ref({title:'',text:'',license:null,aiDeclaration:null,assets:[],works:[],status:'draft',visibility:'private',distribute:true,allowOriginal:false})
const kind=ref('work'), editing=ref(null), profile=ref({name:'',bio:'',accent:'#c8a477',layout:'grid',modules:['works','collections'],cover:null})
const image=id=>'/api/media/'+id+'/display'
async function api(url,options={}) {const r=await fetch('/api/'+url,options), data=await r.json();if(!r.ok)throw Error(data.error);return data}
async function load(){busy.value=true;error.value='';active.value=0;try{me.value=(await api('me')).user;const p=route.path;if(p==='/studio'){if(me.value){studio.value=await api('studio');profile.value=studio.value.profile[0]||profile.value;result.value={}}else result.value={locked:true}}else result.value=await api(p==='/'?'square':p.slice(1))}catch(e){error.value=e.message}finally{busy.value=false}}
watch(()=>route.fullPath,load,{immediate:true})
async function action(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function upload(event){const files=[...event.target.files];await action(async()=>{for(const file of files){const body=new FormData();body.append('file',file);const a=await api('assets',{method:'POST',body});studio.value.asset.unshift(a);form.value.assets.push(a.id)}});event.target.value=''}
async function save(){await action(async()=>{const record=await api(kind.value+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});editing.value=record.id;studio.value=await api('studio')})}
function edit(record){kind.value=record.kind;editing.value=record.id;form.value={...record,license:record.license?.code||null,aiDeclaration:record.aiDeclaration?.code||null}}
function fresh(){editing.value=null;form.value={title:'',text:'',license:null,aiDeclaration:null,assets:[],works:[],status:'draft',visibility:'private',distribute:true,allowOriginal:false}}
async function saveProfile(){await action(async()=>{const old=studio.value.profile[0];profile.value=await api('profile'+(old?'/'+old.id:''),{method:old?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(profile.value)});studio.value=await api('studio')})}
</script>
<template>
 <section class="platform" :style="{'--accent':result.accent||'#c8a477'}">
  <p v-if="error" role="alert" class="notice">{{error}} <button @click="load">重试</button></p>
  <p v-if="busy" role="status">正在处理……</p>
  <template v-if="route.path==='/'">
   <div class="hero" v-if="result.banner?.length" :style="{backgroundImage:`linear-gradient(0deg,#090a0c,transparent),url(${image(result.banner[0].assets[0])})`}"><span>MARKR / 精选摄影</span><h1>{{result.banner[0].title}}</h1><router-link :to="'/work/'+result.banner[0].id">进入作品 →</router-link></div>
   <div v-else class="hero empty"><span>MARKR / 摄影与表达</span><h1>让影像，成为你的语言。</h1><p>一处整理作品的空间，一个分享视角的窗口。</p><router-link to="/studio">整理我的作品 →</router-link></div>
   <div class="section-title"><h2>广场</h2><span>发现独特的视角</span></div>
   <div class="cards"><router-link v-for="w in result.works" :key="w.id" :to="'/work/'+w.id" class="card"><img v-if="w.assets.length" :src="image(w.assets[0])" :alt="w.title" loading="lazy"><div v-else class="text-cover">{{w.text}}</div><h3>{{w.title}}</h3><small>{{w.photographer}}</small></router-link></div>
   <p v-if="!busy&&!result.works?.length" class="empty-state">广场还没有作品。公开发布的作品默认展示于此，作者也可以关闭广场分发。</p>
   <aside class="tool-callout"><div><h2>先创作，再分享</h2><p>无需账号与上传，在浏览器中完成边框、水印和拼图。</p></div><router-link to="/frame-watermark">边框水印</router-link><router-link to="/image-collage">图片拼图</router-link></aside>
  </template>
  <template v-else-if="route.path==='/studio'">
   <div class="section-title"><h1>我的工作台</h1><p>素材 → 草稿 → 作品 → 作品集</p></div>
   <div v-if="result.locked" class="empty-state"><h2>身份入口尚未启用</h2><p>管理员完成身份配置后即可上传与管理作品。离线工具现在可以直接使用。</p><router-link to="/frame-watermark">打开边框水印 →</router-link></div>
   <template v-else-if="me">
    <div class="editor-grid"><form @submit.prevent="save" class="panel"><h2>{{editing?'编辑':'新建'}}{{kind==='work'?'作品':'作品集'}}</h2><label>类型<select v-model="kind" @change="fresh"><option value="work">作品（图片 / 组图 / 文字）</option><option value="collection">作品集</option></select></label><label>标题<input v-model="form.title" required maxlength="200"></label><label>文字<textarea v-model="form.text" rows="4"></textarea></label>
     <template v-if="kind==='work'"><label class="upload">上传成片<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="upload" :disabled="busy"></label><small>每张默认上限 20 MB，仅在主动选择后上传；展示图不含位置元数据。</small><div class="asset-picker"><label v-for="a in studio.asset" :key="a.id"><img :src="image(a.id)" alt="素材缩略图"><input type="checkbox" v-model="form.assets" :value="a.id">选用</label></div><label><input type="checkbox" v-model="form.allowOriginal">允许访客下载原文件（原文件可能含位置元数据）</label></template>
     <div v-else><label v-for="w in studio.work" :key="w.id"><input type="checkbox" v-model="form.works" :value="w.id">{{w.title}}</label><small>作品集不会改变成员作品自身的可见性。</small></div>
     <template v-if="kind==='work'"><label>作者声明<select v-model="form.aiDeclaration"><option :value="null">未声明</option><option :value="aiDeclaration.code">{{aiDeclaration.label}}</option></select></label><label>版权许可<select v-model="form.license"><option :value="null">未选择 CC 许可</option><option v-for="license in licenses" :key="license.code" :value="license.code">{{license.label}} · {{license.name}}</option></select></label><small>请先阅读许可条款，只有权利人能授予许可。未使用 AI 与禁止 AI 训练是不同声明。</small><a v-if="form.license" :href="licenses[form.license].url" target="_blank" rel="noopener noreferrer">阅读所选许可官方说明 ↗</a></template><label>状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">发布</option></select></label><label>可见性<select v-model="form.visibility"><option value="private">私密</option><option value="unlisted">仅链接</option><option value="public">公开</option></select></label><small>仅链接不出现在广场和主页；任何获得链接的人都可以访问。</small><label><input type="checkbox" v-model="form.distribute">公开时进入广场</label><div class="actions"><button :disabled="busy">{{editing?'保存修改':'保存'}}</button><button type="button" @click="fresh">新建</button></div></form>
     <section class="panel"><h2>作品与草稿</h2><div v-for="r in [...studio.work,...studio.collection]" :key="r.id" class="record"><div><strong>{{r.title}}</strong><p>{{r.kind==='work'?'作品':'作品集'}} · {{r.status==='draft'?'草稿':'已发布'}} · {{r.visibility}}</p></div><button @click="edit(r)">编辑</button><router-link :to="'/'+r.kind+'/'+r.id">查看</router-link></div><p v-if="!studio.work.length&&!studio.collection.length">还没有作品，先上传图片或写下文字。</p></section></div>
    <form class="panel profile-editor" @submit.prevent="saveProfile"><h2>摄影师主页</h2><label>名称<input v-model="profile.name" required></label><label>简介<textarea v-model="profile.bio"></textarea></label><label>封面<select v-model="profile.cover"><option :value="null">无封面</option><option v-for="a in studio.asset" :value="a.id" :key="a.id">{{a.id.slice(0,8)}}</option></select></label><label>配色<input type="color" v-model="profile.accent"></label><label>布局<select v-model="profile.layout"><option value="grid">网格</option><option value="column">单列</option></select></label><label>模块顺序<select v-model="profile.modules"><option :value="['works','collections']">作品优先</option><option :value="['collections','works']">作品集优先</option></select></label><button :disabled="busy">保存主页</button><router-link :to="'/profile/'+me">查看主页 →</router-link></form>
   </template>
  </template>
  <template v-else-if="route.path.startsWith('/work/')&&result.id">
   <nav class="viewer-nav"><button @click="$router.back()">← 返回</button><router-link :to="'/profile/'+result.photographer">摄影师主页</router-link></nav><div class="viewer"><img v-if="result.assets?.length" :src="image(result.assets[active])" :alt="result.title"><div v-if="result.assets?.length>1" class="actions"><button @click="active=(active-1+result.assets.length)%result.assets.length">← 上一张</button><span>{{active+1}} / {{result.assets.length}}</span><button @click="active=(active+1)%result.assets.length">下一张 →</button></div></div><div class="caption"><h1>{{result.title}}</h1><p>{{result.text}}</p><p v-if="result.aiDeclaration">{{result.aiDeclaration.label}}</p><a v-if="result.license" :href="result.license.url" target="_blank" rel="noopener noreferrer">{{result.license.label}} · 官方许可说明 ↗</a><a v-if="result.allowOriginal&&result.assets?.length" :href="'/api/media/'+result.assets[active]+'/original'">下载原文件</a></div>
  </template>
  <template v-else-if="route.path.startsWith('/collection/')&&result.id"><button @click="$router.back()">← 返回</button><h1>{{result.title}}</h1><p class="caption">{{result.text}}</p><div class="cards"><router-link v-for="w in result.items" :key="w.id" :to="'/work/'+w.id" class="card"><img v-if="w.assets.length" :src="image(w.assets[0])" :alt="w.title"><h2>{{w.title}}</h2></router-link></div><p v-if="!result.items?.length" class="empty-state">此作品集暂时没有可查看的作品。</p></template>
  <template v-else-if="route.path.startsWith('/profile/')&&result.id"><div class="hero profile-hero" :style="result.cover?{backgroundImage:`linear-gradient(0deg,#090a0c,transparent),url(${image(result.cover)})`}:{}"><h1>{{result.name||'摄影师'}}</h1><p>{{result.bio}}</p></div><section v-for="module in result.modules" :key="module"><h2>{{module==='works'?'作品':'作品集'}}</h2><div class="cards" :class="{column:result.layout==='column'}"><router-link v-for="r in result[module]" :key="r.id" :to="'/'+r.kind+'/'+r.id" class="card"><img v-if="r.assets?.length" :src="image(r.assets[0])" :alt="r.title"><div v-else class="text-cover">{{r.text||'作品集'}}</div><h3>{{r.title}}</h3></router-link></div><p v-if="!result[module]?.length" class="empty-state">暂无公开内容</p></section></template>
 </section>
</template>
<style>
.platform{max-width:1440px;margin:auto;padding:32px clamp(18px,4vw,64px);color:#e9e9eb;--accent:#c8a477}.platform a{color:inherit;text-decoration:none}.platform h1{font-weight:500;letter-spacing:-.04em;font-size:clamp(30px,5vw,62px)}.platform h2{font-weight:500}.platform p{white-space:pre-wrap;color:#a9a9ad}.platform button,.platform .upload{border:1px solid #414146;background:#242429;color:#eee;padding:10px 18px;border-radius:7px;cursor:pointer}.platform button:disabled{opacity:.5}.platform button:focus-visible,.platform a:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.hero{min-height:440px;display:flex;flex-direction:column;justify-content:flex-end;padding:40px;background-position:center;background-size:cover;border-radius:8px;gap:18px}.hero.empty{background:radial-gradient(ellipse at 75% 20%,#292923,transparent 65%),#111215}.hero span{font-size:12px;letter-spacing:.22em;color:var(--accent)}.hero a{color:var(--accent)}.section-title{display:flex;align-items:baseline;justify-content:space-between;margin:42px 0 24px;gap:16px}.section-title span{color:#8b8b91;font-size:13px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.cards.column{grid-template-columns:1fr}.card img{width:100%;height:320px;object-fit:cover;border-radius:5px;display:block}.card h3{margin-top:12px;font-size:17px;font-weight:500}.card small{color:#85858b}.text-cover{height:240px;background:#17181c;padding:28px;overflow:hidden;color:#aaa}.empty-state{padding:60px 20px;text-align:center;border:1px dashed #303035;margin:24px 0}.tool-callout{display:flex;align-items:center;gap:30px;border-top:1px solid #2e2f32;padding:32px 0;margin-top:60px}.tool-callout div{flex:1}.tool-callout a{border:1px solid #444;padding:12px;border-radius:8px}.notice{background:#382525;padding:18px;border-radius:8px;margin-bottom:20px}.editor-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:24px}.panel{padding:26px;background:#141519;border:1px solid #303136;border-radius:10px;margin-bottom:24px}.panel label{display:block;margin:18px 0}.panel input:not([type=checkbox]):not([type=color]),.panel textarea,.panel select{display:block;width:100%;padding:12px;background:#090a0c;color:#ddd;border:1px solid #37373d;border-radius:5px;margin-top:7px;font:inherit}.panel small{display:block;color:#939399}.asset-picker{display:flex;flex-wrap:wrap;gap:10px}.asset-picker img{width:90px;height:70px;object-fit:cover;display:block}.actions{display:flex;gap:16px;align-items:center;margin-top:20px}.record{display:flex;gap:14px;align-items:center;border-bottom:1px solid #303136;padding:18px 0}.record div{flex:1}.profile-editor{max-width:800px}.viewer-nav{display:flex;justify-content:space-between;align-items:center}.viewer{margin-top:24px;text-align:center}.viewer img{max-width:100%;max-height:80vh;object-fit:contain}.viewer .actions{justify-content:center}.caption{max-width:850px;margin:30px auto}.caption p{margin:20px 0;line-height:1.8}.caption a{color:var(--accent)}.profile-hero{margin-bottom:48px}.platform section>h2{margin:32px 0 20px}@media(max-width:800px){.cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.editor-grid{grid-template-columns:1fr}.hero{min-height:360px;padding:28px}.tool-callout{flex-wrap:wrap}.tool-callout div{flex-basis:100%}.section-title{flex-wrap:wrap}.card img{height:220px}}@media(max-width:480px){.cards{grid-template-columns:1fr}.card img{height:auto;max-height:420px}.panel{padding:18px}.record{flex-wrap:wrap}}
</style>
